//#region src/debug.d.ts
type Discrepancy = {
  file: string;
  timestamp: string;
  model: string;
  originalCost: number;
  calculatedCost: number;
  difference: number;
  percentDiff: number;
  usage: {
    input_tokens: number;
    output_tokens: number;
    cache_creation_input_tokens?: number;
    cache_read_input_tokens?: number;
  };
};
type MismatchStats = {
  totalEntries: number;
  entriesWithBoth: number;
  matches: number;
  mismatches: number;
  discrepancies: Discrepancy[];
  modelStats: Map<string, {
    total: number;
    matches: number;
    mismatches: number;
    avgPercentDiff: number;
  }>;
  versionStats: Map<string, {
    total: number;
    matches: number;
    mismatches: number;
    avgPercentDiff: number;
  }>;
};
declare function detectMismatches(claudePath?: string): Promise<MismatchStats>;
declare function printMismatchReport(stats: MismatchStats, sampleCount?: number): void;
//#endregion
export { detectMismatches, printMismatchReport };